package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
        }
        if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.OPEN) {
            claim.setNumber(sheets.nextClaimNumber(claim.getSheetId()));
            claim.setOpenedBy(request.user());
        }
        number.set(new ClaimNumber(claim.getNumber()));
        if (request.target() == ClaimStatus.VOID) {
            claim.setNumber(null);
        }
        if (request.target() == ClaimStatus.SETTLED) {
            // Settling fixes the due at the rate in force on the claim's date; with no rate it stays live (n/a until one is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).getGrade();
            claim.setSettledDue(Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate())));
        }
        claim.setStatus(request.target());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods)
            throws InvalidClaimException {
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getDate()) || periods.isClosed(claim.getSheetId(), date)) {
            throw new InvalidClaimException("No claim dated inside a closed period can be edited");
        }
        claim.setAmount(request.amount());
        claim.setDate(date);
        claim.setNote(request.note());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody ClaimRequest request, Out<ValidClaim> body) throws InvalidClaimException {
        BigDecimal amount = amount(request.amount());
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date is not a date");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        body.set(new ValidClaim(amount, date, note, request.user()));
    }

    /** A claim's amount: 0.00 or more, with at most two decimals. */
    static BigDecimal amount(String raw) throws InvalidClaimException {
        String amount = raw == null ? "" : raw.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be 0.00 or more, with at most two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow; nothing is written. */
public class ClaimStatusRefusedException extends Exception {
    public ClaimStatusRefusedException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to);
    }

    public ClaimStatusRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimStatusRefused {
    public void handle(@Parameter ClaimStatusRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.claim;

/** A claim form that cannot be saved (an amount that is not 0.00 or more with at most two decimals, a bad date); nothing is written. */
public class InvalidClaimException extends Exception {
    public InvalidClaimException(String message) {
        super(message);
    }
}
